            pausedBySaveMoney: true,
            at: new Date().toISOString(),
            window: window ? { pauseAt: window.pauseAt, resumeAt: window.resumeAt, timezone: window.timezone || getCfg().timezone } : null,
            paused,
            cascaded: true,
